    "cssCode": "button {\n  background: transparent;\n  position: relative;\n  padding: 5px 15px;\n  display: flex;\n  align-items: center;\n  font-size: 17px;\n  font-weight: 600;\n  text-decoration: none;\n  cursor: pointer;\n  border: 1px solid rgb(40, 144, 241);\n  border-radius: 25px;\n  outline: none;\n  overflow: hidden;\n  color: rgb(40, 144, 241);\n  transition: color 0.3s 0.1s ease-out;\n  text-align: center;\n}\n\nbutton span {\n  margin: 10px;\n}\n\nbutton::before {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  margin: auto;\n  content: '';\n  border-radius: 50%;\n  display: block;\n  width: 20em;\n  height: 20em;\n  left: -5em;\n  text-align: center;\n  transition: box-shadow 0.5s ease-out;\n  z-index: -1;\n}\n\nbutton:hover {\n  color: #fff;\n  border: 1px solid rgb(40, 144, 241);\n}\n\nbutton:hover::before {\n  box-shadow: inset 0 0 0 10em rgb(40, 144, 241);\n}\n "
