    "cssCode": "button {\n  font-family: inherit;\n  font-size: 20px;\n  background: #212121;\n  color: white;\n  fill: rgb(155, 153, 153);\n  padding: 0.7em 1em;\n  padding-left: 0.9em;\n  display: flex;\n  align-items: center;\n  cursor: pointer;\n  border: none;\n  border-radius: 15px;\n  font-weight: 1000;\n}\n\nbutton span {\n  display: block;\n  margin-left: 0.3em;\n  transition: all 0.3s ease-in-out;\n}\n\nbutton svg {\n  display: block;\n  transform-origin: center center;\n  transition: transform 0.3s ease-in-out;\n}\n\nbutton:hover {\n  background: #000;\n}\n\nbutton:hover .svg-wrapper {\n  transform: scale(1.25);\n  transition: 0.5s linear;\n}\n\nbutton:hover svg {\n  transform: translateX(1.2em) scale(1.1);\n  fill: #fff;\n}\n\nbutton:hover span {\n  opacity: 0;\n  transition: 0.5s linear;\n}\n\nbutton:active {\n  transform: scale(0.95);\n}\n"
