    "cssCode": "button {\n position: relative;\n display: inline-block;\n cursor: pointer;\n outline: none;\n border: 0;\n vertical-align: middle;\n text-decoration: none;\n background: transparent;\n padding: 0;\n font-size: inherit;\n font-family: inherit;\n}\n\nbutton.learn-more {\n width: 12rem;\n height: auto;\n}\n\nbutton.learn-more .circle {\n transition: all 0.45s cubic-bezier(0.65, 0, 0.076, 1);\n position: relative;\n display: block;\n margin: 0;\n width: 3rem;\n height: 3rem;\n background: #282936;\n border-radius: 1.625rem;\n}\n\nbutton.learn-more .circle .icon {\n transition: all 0.45s cubic-bezier(0.65, 0, 0.076, 1);\n position: absolute;\n top: 0;\n bottom: 0;\n margin: auto;\n background: #fff;\n}\n\nbutton.learn-more .circle .icon.arrow {\n transition: all 0.45s cubic-bezier(0.65, 0, 0.076, 1);\n left: 0.625rem;\n width: 1.125rem;\n height: 0.125rem;\n background: none;\n}\n\nbutton.learn-more .circle .icon.arrow::before {\n position: absolute;\n content: \"\";\n top: -0.29rem;\n right: 0.0625rem;\n width: 0.625rem;\n height: 0.625rem;\n border-top: 0.125rem solid #fff;\n border-right: 0.125rem solid #fff;\n transform: rotate(45deg);\n}\n\nbutton.learn-more .button-text {\n transition: all 0.45s cubic-bezier(0.65, 0, 0.076, 1);\n position: absolute;\n top: 0;\n left: 0;\n right: 0;\n bottom: 0;\n padding: 0.75rem 0;\n margin: 0 0 0 1.85rem;\n color: #282936;\n font-weight: 700;\n line-height: 1.6;\n text-align: center;\n text-transform: uppercase;\n}\n\nbutton:hover .circle {\n width: 100%;\n}\n\nbutton:hover .circle .icon.arrow {\n background: #fff;\n transform: translate(1rem, 0);\n}\n\nbutton:hover .button-text {\n color: #fff;\n}"
