    "id": 53,
    "title": "Button",
    "views": "8K",
    "htmlCode": "<button class=\"button\">\n  <div class=\"blob1\"></div>\n  <div class=\"blob2\"></div>\n  <div class=\"inner\">Realism</div>\n</button>\n",
    "cssCode": ".button {\n  cursor: pointer;\n  font-size: 1.4rem;\n  border-radius: 16px;\n  border: none;\n  padding: 2px;\n  background: radial-gradient(circle 80px at 80% -10%, #ffffff, #181b1b);\n  position: relative;\n}\n.button::after {\n  content: \"\";\n  position: absolute;\n  width: 65%;\n  height: 60%;\n  border-radius: 120px;\n  top: 0;\n  right: 0;\n  box-shadow: 0 0 20px #ffffff38;\n  z-index: -1;\n}\n\n.blob1 {\n  position: absolute;\n  width: 70px;\n  height: 100%;\n  border-radius: 16px;\n  bottom: 0;\n  left: 0;\n  background: radial-gradient(\n    circle 60px at 0% 100%,\n    #3fe9ff,\n    #0000ff80,\n    transparent\n  );\n  box-shadow: -10px 10px 30px #0051ff2d;\n}\n\n.inner {\n  padding: 14px 25px;\n  border-radius: 14px;\n  color: #fff;\n  z-index: 3;\n  position: relative;\n  background: radial-gradient(circle 80px at 80% -50%, #777777, #0f1111);\n}\n.inner::before {\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  left: 0;\n  top: 0;\n  border-radius: 14px;\n  background: radial-gradient(\n    circle 60px at 0% 100%,\n    #00e1ff1a,\n    #0000ff11,\n    transparent\n  );\n  position: absolute;\n}\n"
