    "htmlCode": "<button class=\"button\">\n  <svg fill=\"none\" height=\"24\" viewBox=\"0 0 24 24\" width=\"24\" class=\"svg-icon\">\n    <g\n      clip-rule=\"evenodd\"\n      fill-rule=\"evenodd\"\n      stroke=\"#056dfa\"\n      stroke-linecap=\"round\"\n      stroke-width=\"2\"\n    >\n      <path\n        d=\"m3 7h17c.5523 0 1 .44772 1 1v11c0 .5523-.4477 1-1 1h-16c-.55228 0-1-.4477-1-1z\"\n      ></path>\n      <path\n        d=\"m3 4.5c0-.27614.22386-.5.5-.5h6.29289c.13261 0 .25981.05268.35351.14645l2.8536 2.85355h-10z\"\n      ></path>\n    </g>\n  </svg>\n  <span class=\"lable\">Archive</span>\n</button>\n",
    "cssCode": ".button {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 8px 12px 8px 16px;\n  gap: 8px;\n  height: 40px;\n  width: 128px;\n  border: none;\n  background: #056bfa27;\n  border-radius: 20px;\n  cursor: pointer;\n}\n\n.lable {\n  margin-top: 1px;\n  font-size: 19px;\n  line-height: 22px;\n  color: #056dfa;\n  letter-spacing: 1px;\n}\n\n.button:hover {\n  background: #056bfa49;\n}\n\n.button:hover .svg-icon {\n  animation: spin 1s linear infinite;\n}\n\n@keyframes spin {\n  0% {\n    transform: rotate(0deg);\n  }\n\n  25% {\n    transform: rotate(-8deg);\n  }\n\n  50% {\n    transform: rotate(0deg);\n  }\n\n  75% {\n    transform: rotate(8deg);\n  }\n\n  100% {\n    transform: rotate(0deg);\n  }\n}\n"
