    "cssCode": ".main {\n  display: flex;\n  flex-direction: column;\n  gap: 0.5em;\n}\n\n.up {\n  display: flex;\n  flex-direction: row;\n  gap: 0.5em;\n}\n\n.down {\n  display: flex;\n  flex-direction: row;\n  gap: 0.5em;\n}\n\n.card1 {\n  width: 90px;\n  height: 90px;\n  outline: none;\n  border: none;\n  background: white;\n  border-radius: 90px 5px 5px 5px;\n  box-shadow: rgba(50, 50, 93, 0.25) 0px 2px 5px -1px, rgba(0, 0, 0, 0.3) 0px 1px 3px -1px;\n  transition: .2s ease-in-out;\n}\n\n.instagram {\n  margin-top: 1.5em;\n  margin-left: 1.2em;\n  fill: #cc39a4;\n}\n\n.card2 {\n  width: 90px;\n  height: 90px;\n  outline: none;\n  border: none;\n  background: white;\n  border-radius: 5px 90px 5px 5px;\n  box-shadow: rgba(50, 50, 93, 0.25) 0px 2px 5px -1px, rgba(0, 0, 0, 0.3) 0px 1px 3px -1px;\n  transition: .2s ease-in-out;\n}\n\n.twitter {\n  margin-top: 1.5em;\n  margin-left: -.9em;\n  fill: #03A9F4;\n}\n\n.card3 {\n  width: 90px;\n  height: 90px;\n  outline: none;\n  border: none;\n  background: white;\n  border-radius: 5px 5px 5px 90px;\n  box-shadow: rgba(50, 50, 93, 0.25) 0px 2px 5px -1px, rgba(0, 0, 0, 0.3) 0px 1px 3px -1px;\n  transition: .2s ease-in-out;\n}\n\n.github {\n  margin-top: -.6em;\n  margin-left: 1.2em;\n}\n\n.card4 {\n  width: 90px;\n  height: 90px;\n  outline: none;\n  border: none;\n  background: white;\n  border-radius: 5px 5px 90px 5px;\n  box-shadow: rgba(50, 50, 93, 0.25) 0px 2px 5px -1px, rgba(0, 0, 0, 0.3) 0px 1px 3px -1px;\n  transition: .2s ease-in-out;\n}\n\n.discord {\n  margin-top: -.9em;\n  margin-left: -1.2em;\n  fill: #8c9eff;\n}\n\n.card1:hover {\n  cursor: pointer;\n  scale: 1.1;\n  background-color: #cc39a4;\n}\n\n.card1:hover .instagram {\n  fill: white;\n}\n\n.card2:hover {\n  cursor: pointer;\n  scale: 1.1;\n  background-color: #03A9F4;\n}\n\n.card2:hover .twitter {\n  fill: white;\n}\n\n.card3:hover {\n  cursor: pointer;\n  scale: 1.1;\n  background-color: black;\n}\n\n.card3:hover .github {\n  fill: white;\n}\n\n.card4:hover {\n  cursor: pointer;\n  scale: 1.1;\n  background-color: #8c9eff;\n}\n\n.card4:hover .discord {\n  fill: white;\n}"
