    "htmlCode": "<button class=\"button type1\">\n</button>",
    "cssCode": ".button {\n  height: 50px;\n  width: 150px;\n  border: none;\n  border-radius: 10px;\n  cursor: pointer;\n  position: relative;\n  overflow: hidden;\n  transition: all 0.5s ease-in-out;\n}\n\n.button:hover {\n  box-shadow: .5px .5px 150px #252525;\n}\n\n.type1::after {\n  content: \"Thanks\";\n  height: 50px;\n  width: 150px;\n  background-color: #008080;\n  color: #fff;\n  position: absolute;\n  top: 0%;\n  left: 0%;\n  transform: translateY(50px);\n  font-size: 1.2rem;\n  font-weight: 600;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: all 0.5s ease-in-out;\n}\n\n.type1::before {\n  content: \"Hover Me\";\n  height: 50px;\n  width: 150px;\n  background-color: #fff;\n  color: #008080;\n  position: absolute;\n  top: 0%;\n  left: 0%;\n  transform: translateY(0px) scale(1.2);\n  font-size: 1.2rem;\n  font-weight: 600;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: all 0.5s ease-in-out;\n}\n\n.type1:hover::after {\n  transform: translateY(0) scale(1.2);\n}\n\n.type1:hover::before {\n  transform: translateY(-50px) scale(0) rotate(120deg);\n}"
