    "cssCode": "button {\n  height: 4em;\n  width: 15em;\n  border: none;\n  border-radius: 40px;\n  background-color: #fff;\n  cursor: pointer;\n}\n\nbutton span {\n  z-index: 1;\n  display: inline-block;\n  background-color: black;\n  height: 3em;\n  width: 11.5em;\n  border-radius: 25px;\n  color: #fff;\n  line-height: 55px;\n  font-size: 18px;\n  letter-spacing: 3px;\n  transition: all 0.5s;\n}\n\nbutton .container {\n  z-index: -1;\n  width: 0;\n  position: relative;\n  display: flex;\n  justify-content: center;\n  transform: translateY(-50px);\n  transition: all 0.4s;\n}\n\nbutton .container svg {\n  padding: 0 10px;\n}\n\nbutton:hover span {\n  width: 0;\n}\n\nbutton:hover .container {\n  z-index: 2;\n  width: 100%;\n}\n"
