    "cssCode": ".button {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 10px 15px;\n  gap: 15px;\n  background-color: #007ACC;\n  outline: 3px #007ACC solid;\n  outline-offset: -3px;\n  border-radius: 5px;\n  border: none;\n  cursor: pointer;\n  transition: 400ms;\n}\n\n.button .text {\n  color: white;\n  font-weight: 700;\n  font-size: 1em;\n  transition: 400ms;\n}\n\n.button svg path {\n  transition: 400ms;\n}\n\n.button:hover {\n  background-color: transparent;\n}\n\n.button:hover .text {\n  color: #007ACC;\n}\n\n.button:hover svg path {\n  fill: #007ACC;\n}"
