    "cssCode": ".social-login-icons {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  -webkit-box-reflect: below 5px linear-gradient(transparent, #00000055);\n}\n.social-login-icons svg {\n  width: 40px;\n}\n\n.social-icon-1,\n.social-icon-1-1,\n.social-icon-2,\n.social-icon-2-2,\n.social-icon-3,\n.social-icon-3-3,\n.social-icon-4,\n.social-icon-4-4 {\n  width: 50px;\n  height: 50px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50px;\n  margin: 20px 0 0px 0;\n}\n\n.icon svg {\n  fill: #111;\n}\n\n.socialcontainer {\n  height: 80px;\n  overflow: hidden;\n}\n.social-icon-1 {\n  transition-duration: 0.4s;\n  background-color: rgb(0, 0, 0);\n  transition-timing-function: cubic-bezier(0.46, -0.78, 0.5, 1.56);\n}\n.social-icon-1 svg,\n.social-icon-2 svg,\n.social-icon-3 svg,\n.social-icon-4 svg {\n  opacity: 0;\n  transition-duration: 0.5s;\n  transition-delay: 0.2s;\n}\n.social-icon-1-1 {\n  transition-duration: 0.4s;\n  background-color: rgb(0, 0, 0, 0);\n}\n.socialcontainer:hover .social-icon-1 {\n  transform: translateY(-70px);\n}\n.socialcontainer:hover .social-icon-1 svg,\n.socialcontainer:hover .social-icon-2 svg,\n.socialcontainer:hover .social-icon-3 svg,\n.socialcontainer:hover .social-icon-4 svg {\n  opacity: 1;\n}\n.social-icon-2 {\n  transition-duration: 0.4s;\n  transition-timing-function: cubic-bezier(0.46, -0.78, 0.5, 1.56);\n  background: linear-gradient(\n    72.44deg,\n    #ff7a00 11.92%,\n    #ff0169 51.56%,\n    #d300c5 85.69%\n  );\n}\n.socialcontainer:hover .social-icon-2 {\n  transform: translateY(-70px);\n}\n.social-icon-3 {\n  transition-duration: 0.4s;\n  transition-timing-function: cubic-bezier(0.46, -0.78, 0.5, 1.56);\n  background: #316ff6;\n}\n\n.socialcontainer:hover .social-icon-3 {\n  transform: translateY(-70px);\n}\n.social-icon-4 {\n  transition-duration: 0.4s;\n  transition-timing-function: cubic-bezier(0.46, -0.78, 0.5, 1.56);\n\n  background: linear-gradient(\n    180deg,\n    rgba(129, 34, 144, 1) 0%,\n    rgba(77, 34, 124, 1) 91%\n  );\n}\n\n.socialcontainer:hover .social-icon-4 {\n  transform: translateY(-70px);\n}\n"
